/// <summary>
/// CB626_TMSEngineSOPackingSlip
/// Class responsible for the TSIG PAL calculation (with CCR)
/// </summary>
final class METTMSShipmentItemGroupUOM_PALCCR extends METTMSShipmentItemGroupUOM_PAL
{
}

Method.Source:
void initParameters(METTMSEngineSalesOrderProccessLinesTmp _processLinesTmp,
                    METTMSEngineSalesOrderProccessLinesTmp _lineTmpSum,
                    METTMSShipmentOrderIdentifier          _tmsShipmentOrderIdentifier,
                    InventLocationId                       _headerInventLocationId,
                    boolean                                _isToteCustomer,
                    Set                                    _ccrToteIds,
                    SalesId                                _salesId,
                    WMSPickingRouteId                      _pickingRouteId,
                    boolean                                _isKegItem = false)
{
    super(_processLinesTmp, _lineTmpSum, _tmsShipmentOrderIdentifier, _headerInventLocationId, _isToteCustomer, _ccrToteIds, _salesId, _pickingRouteId, _isKegItem);

    this.initCCRParameters();
}

/// <summary>
/// Method to calculate TSIG volume (cube)
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG volume (cube)</returns>
METWHSPalletVolume cube(METQty _quantity)
{
    METWHSPalletVolume ret = super(_quantity);

    if (!isKegItem)
    {
        if (isToteCustomer)
        {
            // Sum of (CCRWhs_ToteVolume * CCR_RepackContainersByCommodity for this CCR_LineCommodity) from all supplying warehouses
            ret += sumRepackContainersByCommodityToteVolumeCCR;
        }
        else
        {
            // Sum of (CCRWhs_CaseVolume * Count(CCR_RepackContainersByCommodity) for this CCR_LineCommodity) from all supplying warehouses
            ret += sumRepackContainersByCommodityCaseVolumeCCR;
        }
    }

    return ret;
}

/// <summary>
/// Method to calculate TSIG quantity
/// </summary>
/// <param name = "_cube">TSIG volume (cube)</param>
/// <returns>TSIG quantity</returns>
METQty quantity(METWHSPalletVolume _cube = 0)
{
    return super(_cube);
}

/// <summary>
/// Method to calculate TSIG weight
/// </summary>
/// <param name = "_quantity">TSIG quantity</param>
/// <returns>TSIG weight</returns>
METWHSPalletWeight weight(METQty _quantity)
{
    METQty ret;

    // Keg “PAL” TSIGs are created under the same conditions as described in the same section in the CB624 FSD 
    // and with the same logic. Kegs will not have CCR data.
    // DoesCustUseTotes = N same calc as non CCR
    // calc is the same except when DoesCustUseTotes = Y
    ret = super(_quantity);

    if (isToteCustomer)
    {
        // Sum of (CCRWhs_ToteWeight * Count(CCR_RepackContainersByCommodity) for this CCR_LineCommodity) ) from all supplying warehouses
        ret += sumRepackContainersByCommodityToteWeightCCR;
    }        

    return ret;
}
